import{_ as o,l as i,o as e,c as E,v as t,p as l,x as n,d as s,i as A,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"实盘漂移监测","description":"","frontmatter":{"title":"实盘漂移监测","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/live-drift-monitor.md","filePath":"quant/live-drift-monitor.md","lastUpdated":1789023840000}'),h={name:"quant/live-drift-monitor.md"};function d(m,a,B,u,C,c){const r=i("Mermaid");return e(),E("div",null,[a[1]||(a[1]=t('<h1 id="实盘漂移监测" tabindex="-1">实盘漂移监测 <a class="header-anchor" href="#实盘漂移监测" aria-label="Permalink to &quot;实盘漂移监测&quot;">​</a></h1><div class="epigraph"><p>把递归残差依次累加，若关系在样本中途换了，累加路径会像带漂移的随机游走一样穿出常数参数下的边界。</p><footer>—— Brown, Durbin and Evans, Techniques for Testing the Constancy of Regression Relationships over Time, JRSS-B, 1975</footer></div><p>回测通过、模拟通过、小规模实盘开始赚钱之后，问题变成：现在的 alpha 还是当时冻结的那一个吗？漂移监测是顺序检验，不是再做一次全样本 t。<a href="/quant/cusum-mosum">CUSUM / MOSUM</a> 把回归残差累加或滑动求和，参数一旦不稳就穿带；在交易里，监测对象换成 IC、扣费后残差、实施缺口、以及与研究路径的跟踪误差。McLean–Pontiff 提醒：公开信号有一个朝下的期望衰减，监测的原假设不应是「IC 永远等于回测」，而应是「IC 落在预扣偏差与拥挤之后的预算带里」。Hou–Xue–Zhang 提醒：若实盘宇宙滑向微盘与等权才能维持 t，经济上已经漂移。本篇写听什么、何时停、以及如何与<a href="/quant/research-sim-prod">研究-模拟-实盘隔离</a>兼容——监测是只读的，不能回头改定义把实盘变成新的样本内。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>实盘路径短，Lo（2002）意义上的夏普标准误很大，用三个月夏普去「验证」研究是把噪声当证据。需要的是对预指定统计量的顺序检验：每天或每周更新，控制一类错误，穿越才触发。对象至少四条：(1) 截面 IC 或 RankIC 相对冻结期均值；(2) 扣费后残差相对模拟器；(3) 实施缺口相对 TCA 基准；(4) 与已部署因子的相关，捕获拥挤漂移。任一单条都不够：IC 仍在但缺口扩大，是执行漂移；缺口稳定但 IC 下降，是 alpha 漂移；两者都稳但相关上升，是拥挤漂移。</p><p>原假设必须含衰减预算。若把原假设设成「IC 等于回测全样本」，McLean–Pontiff 的 −26% 到 −58% 会让几乎所有公开因子迟早报警，报警没有信息量。预指定一条衰减带：例如发表后折扣后的均值，加减冻结期标准误的若干倍，或一条允许随时间缓降的斜坡。穿出带才叫漂移。Hou–Xue–Zhang 的加权手续应在实盘同样执行：监测市值加权 IC，而不是只监测等权——等权可以在微盘上假装没有漂移。</p><h3 id="漂移不是回撤" tabindex="-1">漂移不是回撤 <a class="header-anchor" href="#漂移不是回撤" aria-label="Permalink to &quot;漂移不是回撤&quot;">​</a></h3><p>回撤可以由共同因子、利率、一次宏观冲击造成，alpha 仍在。漂移是条件期望变了：给定你的信号，未来收益的映射不再是冻结时的那条。用净值回撤当监测，会在系统性坏年停掉仍然有效的风险溢价，也会在拥挤赚钱的阶段放过正在变薄的错误定价。正确的残差是相对风险模型与相对模拟器，而不是相对零。vol targeting 的 CTA 在波动上升时净值会缩，那是规则，不是 IC 漂移。</p><p><span class="marginnote">纸上交易若由人盯着实时价格点「假如成交」，不能当监测样本：没有拒单、没有部分成交、没有迟到。监测必须接真实账户或至少接与实盘同一套状态机的模拟成交。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>IC 的 CUSUM。</strong> 每日截面 RankIC 减预算均值，标准化后累加。参数恒定、近似短记忆时，路径有临界带；穿带则拒绝恒定。MOSUM 用固定窗对近期断裂更敏感，适合快信号。块长度要覆盖换手周期，避免把一周的噪声当成断裂。与 Bai–Perron 的差别：后者是事后全局切段，监测是在线的，不能回头用未来残差估 \\(\\tau\\)。</p><p><strong>实施缺口。</strong> 决策价到成交的短fall 对 TCA 预测回归，监听残差 CUSUM。缺口扩大而 IC 仍在，应先查参与率、场内、借券，而不是先关信号。缺口与 IC 同时坏，才像 alpha 与市场冲击一起变了，见<a href="/quant/strategy-capacity-decay">策略容量</a>。</p><p><strong>相关与拥挤。</strong> 实盘组合与文献因子、与内部已部署因子的滚动相关，以及残差 PCA 第一主成分解释方差。相关穿出冻结期分位，触发降杠杆而不是立刻清盘——<a href="/quant/crowded-alpha-decay">拥挤衰减</a>里，做空拥挤需要另有独立腿。</p><p><strong>多重监测的错误率。</strong> 四条路径同时听，一类错误会膨胀。预指定主路径（通常是扣费后残差或加权 IC）与若干辅助路径；辅助只降杠杆或开票，主路径穿带才停机。不要每天根据哪条「看起来坏」临时改主路径。</p><h3 id="停机规则与研究隔离" tabindex="-1">停机规则与研究隔离 <a class="header-anchor" href="#停机规则与研究隔离" aria-label="Permalink to &quot;停机规则与研究隔离&quot;">​</a></h3><p>穿带之后的动作必须预先写成状态机：警告 → 降参与率 → 冻结加仓 → 停机。停机后的复盘在研究账户进行，新参数是新试验，带新的版本号与新的 \\(N\\)，见过拟合作为风险。实盘监测日志只读，禁止把报警日当成新的样本内起点去重估信号。Arnott–Harvey–Markowitz 的协议在这里最硬：看过结果再改定义，样本外就消失了。</p><p><span class="marginnote">LLM 挖掘流水线更容易漂：生成器每周换模板，实盘上的「因子」其实是一条不断改写的搜索轨迹。监测必须绑在冻结的表达式哈希上，而不是绑在策略中文名上。表达式一变，计时器归零，当作新产品。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>统计机制是顺序检验的边界：在原假设下，累积和收敛到布朗桥一类过程，边界按一类错误校准。金融里误差有肥尾与波动聚类，名义边界会低估穿带概率，应用稳健标准化或对残差做波动缩放，并在冻结期做一次假发现校准。经济机制是：错误定价被交易进去、体制切换、成本结构变化、执行场内变化，都会把 \\(E[r\\mid x]\\) 挪走。McLean–Pontiff 给出公开信号朝下挪的平均速度；拥挤与融资给出加速项；Hou–Xue–Zhang 给出「看起来没挪、其实只是滑进微盘」的伪稳定。</p><p>实施缺口的漂移常常先于 IC。流动性供给撤退时，同样的信号、同样的 \\(p\\)，短fall 先升，IC 还来得及在价格上实现。监测若只看 PnL，会把执行问题记成 alpha 死亡，下一步去翻信号，错过 \\(Q/D\\)。反过来，IC 已死而缺口看起来正常，是因为已经没什么量可做——低换手掩盖了死亡。两条一起看。</p><h3 id="预算带如何吸收「正常衰减」" tabindex="-1">预算带如何吸收「正常衰减」 <a class="header-anchor" href="#预算带如何吸收「正常衰减」" aria-label="Permalink to &quot;预算带如何吸收「正常衰减」&quot;">​</a></h3><p>把发表后折扣写成原假设均值 \\(\\mu_t=\\mu_{\\mathrm{IS}}\\times(1-\\delta_t)\\)，\\(\\delta_t\\) 可取 McLean–Pontiff 的阶梯（样本外 26%、发表后 58%）或一条更慢的指数。预算带围绕 \\(\\mu_t\\)，而不是围绕 \\(\\mu_{\\mathrm{IS}}\\)。这样，符合文献平均衰减的公开因子不会天天报警；真正异常的是相对文献平均还要更快的崩塌，或向微盘集中的伪稳定。经济显著性要求：即使落在预算带内，若 \\(\\mu_t\\) 已经低于成本 MC 的左尾，也应停机——监测通过但经济上已无边缘，见<a href="/quant/econ-vs-stat-sig">经济 vs 统计</a>。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>CUSUM 对原假设「参数恒定」敏感，对「从来没有关系」不区分：本来就不平稳的残差会穿任何带。因此监测加在已经通过形成期筛选的策略上，而不是用来发现新因子。短样本的峰度让边界很吵，应报告对标准化方式的敏感性。A 股停牌与涨跌停造成 IC 缺失日，累加时要明确：跳过、还是按零填。按零填会低估漂移。</p><p>不要用监测去替代验证集。没有冻结期、没有预指定统计量的「我们一直在看实盘」，只是把实盘当第三折交叉验证。也不要在穿带之后用同一段实盘去证明「改完参数就好了」——那是泄漏。小规模实盘的作用是校准冲击与完成率，给监测提供 TCA 基准，不是给 t 统计量提供新样本。</p><p><span class="marginnote">出处：Brown, Durbin and Evans, <em>JRSS-B</em>, 1975；Ploberger and Krämer, <em>Econometrica</em>, 1992；McLean and Pontiff, <em>JF</em>, 2016；Hou, Xue and Zhang, <em>RFS</em>, 2020；Lo, <em>FAJ</em>, 2002；Arnott, Harvey and Markowitz, <em>JFDS</em>, 2019。顺序监听的交易用法见 CUSUM/MOSUM 篇；隔离见研究-模拟-实盘。</span></p>',26)),(e(),l(p,null,{default:n(()=>[A(r,{id:"mermaid-76",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREEZE%5B%22%E5%86%BB%E7%BB%93%E8%A1%A8%E8%BE%BE%E5%BC%8F%E4%B8%8E%E9%A2%84%E7%AE%97%E5%B8%A6%22%5D%20--%3E%20IC%5B%22%E5%8A%A0%E6%9D%83%20IC%20%2F%20RankIC%22%5D%0A%20%20FREEZE%20--%3E%20GAP%5B%22%E5%AE%9E%E6%96%BD%E7%BC%BA%E5%8F%A3%20vs%20TCA%22%5D%0A%20%20FREEZE%20--%3E%20CORR%5B%22%E4%B8%8E%E5%B7%B2%E9%83%A8%E7%BD%B2%E5%9B%A0%E5%AD%90%E7%9B%B8%E5%85%B3%22%5D%0A%20%20IC%20--%3E%20CUSUM%5B%22CUSUM%20%2F%20MOSUM%22%5D%0A%20%20GAP%20--%3E%20CUSUM%0A%20%20CORR%20--%3E%20AUX%5B%22%E8%BE%85%E5%8A%A9%EF%BC%9A%E9%99%8D%E6%9D%A0%E6%9D%86%22%5D%0A%20%20CUSUM%20--%3E%20MAIN%7B%22%E4%B8%BB%E8%B7%AF%E5%BE%84%E7%A9%BF%E5%B8%A6%3F%22%7D%0A%20%20MAIN%20--%3E%7C%E5%90%A6%7C%20LIVE%5B%22%E7%BB%A7%E7%BB%AD%20%C2%B7%20%E5%8F%AA%E8%AF%BB%E6%97%A5%E5%BF%97%22%5D%0A%20%20MAIN%20--%3E%7C%E6%98%AF%7C%20STOP%5B%22%E8%AD%A6%E5%91%8A%20%E2%86%92%20%E9%99%8D%E5%8F%82%E4%B8%8E%20%E2%86%92%20%E5%81%9C%E6%9C%BA%22%5D%0A%20%20STOP%20--%3E%20RS%5B%22%E7%A0%94%E7%A9%B6%E8%B4%A6%E6%88%B7%E6%96%B0%E8%AF%95%E9%AA%8C%22%5D%0A%20%20AUX%20--%3E%20LIVE%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>实盘漂移监测是对预指定统计量的顺序检验，原假设应含 McLean–Pontiff 一类衰减预算，而不是「IC 等于回测」。</li><li>主路径看加权 IC 或扣费残差，辅助路径看缺口与拥挤相关；停机规则必须预先写成状态机。</li><li>等权微盘上的伪稳定不是没有漂移；Hou–Xue–Zhang 的加权手续应在监测里同样执行。</li><li>监测只读，穿带后的改动是新试验；禁止把实盘报警日变成新的样本内。</li><li>漂移不是回撤；执行缺口与 alpha 死亡要分开听。</li><li>出处：Brown–Durbin–Evans, <em>JRSS-B</em>, 1975；McLean–Pontiff, <em>JF</em>, 2016；Hou–Xue–Zhang, <em>RFS</em>, 2020；Arnott–Harvey–Markowitz, <em>JFDS</em>, 2019。</li></ul>',2))])}const S=o(h,[["render",d]]);export{_ as __pageData,S as default};
